class QRNNModel {
public:
  static const int INPUT_SIZE = 1;
  static const int K          = 3;

  /**
   * Run a forward pass and write K quantile estimates to *output*.
   *
   * @param x       Input array of length INPUT_SIZE.
   * @param output  Output array of length K (caller-allocated).
   */
  void predict(const float* x, float* output) {
    float buf_a[64];
    float buf_b[64];
    const float* in_ptr  = x;
    float*       out_ptr = buf_a;

    // --- Hidden layer 0  (1 → 64, relu) ---
    for (int k = 0; k < 64; k++) {
      float acc = h0_b[k];
      for (int j = 0; j < 1; j++)
        acc += h0_w[k][j] * in_ptr[j];
      if (acc < 0.0f) acc = 0.0f;
      out_ptr[k] = acc;
    }

    // Swap buffers
    in_ptr  = out_ptr;
    out_ptr = (out_ptr == buf_a) ? buf_b : buf_a;

    // --- Hidden layer 1  (64 → 64, relu) ---
    for (int k = 0; k < 64; k++) {
      float acc = h1_b[k];
      for (int j = 0; j < 64; j++)
        acc += h1_w[k][j] * in_ptr[j];
      if (acc < 0.0f) acc = 0.0f;
      out_ptr[k] = acc;
    }

    // Swap buffers
    in_ptr  = out_ptr;
    out_ptr = (out_ptr == buf_a) ? buf_b : buf_a;

    // --- Quantile head (64 → 3) ---
    float raw[3];
    for (int k = 0; k < 3; k++) {
      float acc = head_b[k];
      for (int j = 0; j < 64; j++)
        acc += head_w[k][j] * in_ptr[j];
      raw[k] = acc;
    }

    // Monotone decode: base + cumsum(softplus(deltas))
    output[0] = raw[0];   // base quantile (unconstrained)
    for (int k = 1; k < 3; k++) {
      // softplus with overflow guard: log(1 + exp(x)), clamped at x = 88
      float x_sp = raw[k] < 88.0f ? raw[k] : 88.0f;
      float sp   = logf(1.0f + expf(x_sp));
      output[k]  = output[k - 1] + sp;   // cumulative sum
    }
  }
};